"""Self-tests for the checkpointed journal recovery (development helper)."""
import json, struct, subprocess, sys, zlib, pathlib, random

HERE = pathlib.Path(__file__).resolve().parent

def rec(seq, kind, txid, payload=b"", plen=None, crc=None):
    if plen is None: plen = len(payload)
    h = struct.pack("<IIBI", plen, seq, kind, txid)
    body = h + payload
    if crc is None: crc = zlib.crc32(body) & 0xFFFFFFFF
    return body + struct.pack("<I", crc)

def patch_payload(page, off, data):
    return struct.pack("<HHH", page, off, len(data)) + data

def commit_payload(payloads, count=None, digest=None):
    if count is None: count = len(payloads)
    if digest is None: digest = zlib.crc32(b"".join(payloads)) & 0xFFFFFFFF
    return struct.pack("<II", count, digest)

def run(reqs):
    inp = "".join(json.dumps(r) + "\n" for r in reqs)
    p = subprocess.run([sys.executable, str(HERE / "main.py")], input=inp, text=True,
                       capture_output=True, cwd=HERE)
    assert p.returncode == 0, p.stderr
    lines = [l for l in p.stdout.splitlines() if l.strip()]
    assert len(lines) == len(reqs), (len(lines), len(reqs), p.stdout)
    return [json.loads(l) for l in lines]

